    @Then("^User Login to Claims as (.*)$")
    public void userLoginAsClaimsExaminer(String user) throws InterruptedException {
        System.out.println("Login into CV");
        base.Common.sleep(500);//50000
        if (user.equalsIgnoreCase("Examiner"))
            lp.loinginCVSSO(Config.userNameExaminer, Config.passWordExaminer);
        else if (user.equalsIgnoreCase("Tech"))
            lp.loinginCVSSO(Config.userNameTech, Config.passWordTech);
        else if (user.equalsIgnoreCase("Admin"))
            lp.loinginCVSSO(Config.sysadminusername, Config.sysadminpassword);
        else if (user.equalsIgnoreCase("RSLISystemAdmin"))
            lp.loinginCVSSO(Config.userNameRSLISystemAdmin, Config.passWordRSLISystemAdmin);
        else if (user.equalsIgnoreCase("ReadOnlyUser"))
            lp.loinginCVSSO(Config.userNamereadonly, Config.passWordreadonly);
        else if (user.equalsIgnoreCase("ClaimsSysAdmin"))
            lp.loinginCVSSO(Config.userNameClaimsSysAdmin, Config.passWordClaimsSysAdmin);
        else if (user.equalsIgnoreCase("ClaimTechMgmt"))
            lp.loinginCVSSO(Config.userNameClaimTechMgmt, Config.passWordClaimTechMgmt);
        else if (user.equalsIgnoreCase("ClaimsMngusername"))
            lp.loinginCVSSO(Config.ClaimsMngusername, Config.ClaimsMngusernamePWD);
        else if (user.equalsIgnoreCase("MatrixFinancial"))
            lp.loinginCVSSO(Config.ClaimsFinacialMgrUN, Config.ClaimsFinacialMgrPWD);
        else if (user.equalsIgnoreCase("Implementation"))
            lp.loinginCVSSO(Config.Implementation1UN, Config.Implementation1PWD);
        base.Common.sleep(600);//4000
        base.Common.handleSFErrorPopup(driver);
    }

