    @And("^Verify (.*) Link In Home Page (\\d+)$")
    public void verifyHomepageLinks(String lnkName, int rownumber) throws Exception {
        System.out.println("\n[--- Start Step ---]");
        Hooks.iterationID = rownumber;
        System.out.println("[Step Iteration# " + rownumber + " ]");
        //------------------------------------
        if (lnkName.equalsIgnoreCase("TLO")) {
            boolean isTLOisplayed = false;
            try {
                isTLOisplayed = driver.findElement(By.xpath("//strong[contains(text(),'Quick Links')]/ancestor::span//strong[text()='TLO']")).isDisplayed();
            } catch (NoSuchElementException e) {
                isTLOisplayed = false;
            }
            Assert.assertTrue(isTLOisplayed, "TLO is not displayed on the page!");
        } else if (lnkName.equalsIgnoreCase("EDPOAC")) {
            boolean isEDPOACisplayed = false;
            try {
                isEDPOACisplayed = driver.findElement(By.xpath("//strong[contains(text(),'Quick Links')]/ancestor::span//strong[text()='EDP/OAC']")).isDisplayed();
            } catch (NoSuchElementException e) {
                isEDPOACisplayed = false;
            }
            Assert.assertTrue(isEDPOACisplayed, "EDPOAC is not displayed on the page!");
        } else if (lnkName.equalsIgnoreCase("MAState")) {
            boolean isMAStateDisplayed = false;
            try {
                isMAStateDisplayed = driver.findElement(By.xpath("//strong[contains(text(),'Quick Links')]/ancestor::span//strong[text()='MA State']")).isDisplayed();
            } catch (NoSuchElementException e) {
                isMAStateDisplayed = false;
            }
            Assert.assertTrue(isMAStateDisplayed, "MAState is not displayed on the page!");
        } else if (lnkName.equalsIgnoreCase("IntelliScript")) {
            boolean isIntelliScriptisplayed = false;
            try {
                isIntelliScriptisplayed = driver.findElement(By.xpath("//strong[contains(text(),'Quick Links')]/ancestor::span//strong[text()='Intelli Script']")).isDisplayed();
            } catch (NoSuchElementException e) {
                isIntelliScriptisplayed = false;
            }
            Assert.assertTrue(isIntelliScriptisplayed, "Intelli Script is not displayed on the page!");
        }
        base.Common.takeScreenshot(sc, driver, "Homepage Quick Ljnks");
    }

