    @Given("^user login CV (.*) times$")
    public void background_userLoginCV(int a) throws Throwable {
        if (a == 0) {
            System.out.println("Browser Maximized");
            sc.write("Login into CV");
            lp.login(Config.userName, Config.passWord);
        } else {
            Hooks.loginloop++;
            System.out.println("Running scenario Loop: " + Hooks.loginloop);
            System.out.println("Background to run login loop: " + a);
            if (Hooks.loginloop <= a) {
                sc.write("Start login : " + Hooks.loginloop);
                lp.login(Config.userName, Config.passWord);
            } else {
                System.out.println("Login NOT required, go with open session to run sceanrio step : [ " + sc.getName() + " ]");
            }
        }
        //lp.setRunningTCDisplayInPageHeader("Scenario 1");
        int NotificationCount = cp.Notification.size();
        if (NotificationCount > 0) {
            base.Common.waitAndClick(driver, cp.Notification_button, sc, "Notification_button", false, false, true, 30, 2);
            base.Common.waitAndClick(driver, cp.MarkAllAsread_lnk, sc, "Notification_button", false, false, true, 30, 2);
            base.Common.waitAndClick(driver, cp.CloseNotification, sc, "CloseNotification", false, false, true, 30, 2);
        }
    }

