    @And("^Create New Policy (\\d+)$")
    public void createPolicy(int rownumber) throws Exception {
        uniquePolicyName = "";
        System.out.println("\n[--- Start Step ---]");
        Hooks.iterationID = rownumber;
        System.out.println("[Step Iteration# " + rownumber + " ]");
//        String prodname = (dataMap.get(rownumber).get("ProdName").trim());
//        String custFilename = Common.getProductdatafile(prodname);
        String prodname = dataMap.get(rownumber).get("ProdName").trim();
        String custFilename = cv.Common.Common.getProductdatafile(prodname);
        //------------------------------------
        tcid = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") || FeatureDriver.testPlan.contains("BACKLOG") ? dataMap.get(rownumber).get("TCID") : "");
        tcname = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") || FeatureDriver.testPlan.contains("BACKLOG") ? dataMap.get(rownumber).get("TCName") : "");
        if (tcid != null && !tcid.trim().equalsIgnoreCase(""))
            base.Common.writeconsule(sc, "[ TCID: " + tcid + " TCName: " + tcname + "]");
        //-----------------------------------
        DateFormat dateformat = new SimpleDateFormat("YYYYss");
        Date date = new Date();
        String uniquePolicyName = dataMap.get(rownumber).get("PolicyName_Prefix") + "0000" + dateformat.format(date);
        String uniProdName = base.Common.readPropertFile(custFilename, Common.convertKeyWithPrefix("Product", tcid));
        System.out.println("policyName -->" + uniquePolicyName);
        System.out.println("uniProdName -->" + uniProdName);
        base.Common.Click(driver, By.xpath("//span[@class='slds-truncate'][(text()='Policies')]/../..//lightning-icon"), sc, "ProductMegaMenu", true, false, true, false, 5, 2);
        base.Common.sleep(3000);
        base.Common.Click(driver, By.xpath("//span[text()='New Policy']"), sc, "New", true, false, true, false, 5, 2);
        if (dataMap.get(rownumber).get("ProdName").equalsIgnoreCase("STD")) {
            pl.CreateNewPolicy1(uniquePolicyName, dataMap.get(rownumber).get("PolicyVersion"), cp.getproductName(dataMap.get(rownumber).get("ProdName").trim()), dataMap.get(rownumber).get("Company_Code"), dataMap.get(rownumber).get("PolicyStatus"), dataMap.get(rownumber).get("DateofPolicy"));
        } else {
            pl.CreateNewPolicy(uniquePolicyName, dataMap.get(rownumber).get("PolicyVersion"), uniProdName, dataMap.get(rownumber).get("Company_Code"), dataMap.get(rownumber).get("PolicyStatus"), dataMap.get(rownumber).get("DateofPolicy"));
        }
        System.out.println("[--- End to Enter data in Policy  screen ---]");
        Thread.sleep(4000);
        String PolicyDetails = base.Common.waitAndGetText(driver, By.xpath("//span[text()='Policy Number']/ancestor::div[@class='slds-form-element slds-hint-parent test-id__output-root slds-form-element_edit slds-form-element_readonly is-stacked is-stacked-not-editing']//lightning-formatted-text"), sc, "Policy", false, true, 4, 2);
        System.out.println("PolicyName--> " + prodname);
        if (dataMap.get(rownumber).get("ProdName").equalsIgnoreCase("STD")) {
            base.Common.writePropertFile(custFilename, Common.convertKeyWithPrefix("Policy_ID", tcid), PolicyDetails);
        } else {
            base.Common.writePropertFile(custFilename, Common.convertKeyWithPrefix("Policy", tcid), PolicyDetails);
        }
        /*String ExpectedPN = base.Common.readPropertFile(custFilename, Common.convertKeyWithPrefix("Contact".trim().toUpperCase(), tcid));
        System.out.println("PolicyName--> " + ExpectedPN);*/
        base.Common.writeconsule(sc, "PolicyName -->" + PolicyDetails);
        Hooks.message = Hooks.message + "Policy Created Successfully  --> Policy: [" + PolicyDetails + "]\n";
    }

