    @And("^Verify Record Types In Contacts (\\d+)$")
    public void verifyRecordTypesInContacts(int rownumber) throws InterruptedException, IOException {
        System.out.println("\n[--- Start Step ---]");
        Hooks.iterationID = rownumber;
        System.out.println("[Step Iteration# " + rownumber + " ]");
        //rownumber = rownumber - 1;
        //------------------------------------
        tcid = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") || FeatureDriver.testPlan.contains("BACKLOG") ? dataMap.get(rownumber).get("TCID") : "");
        tcname = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") || FeatureDriver.testPlan.contains("BACKLOG") ? dataMap.get(rownumber).get("TCName") : "");
        if (tcid != null && !tcid.trim().equalsIgnoreCase(""))
            base.Common.writeconsule(sc, "[ TCID: " + tcid + " TCName: " + tcname + "]");
        //-----------------------------------
        List<String> expectedOptions = Arrays.asList("Employee", "Assignee", "Attorney", "Beneficiary",
                "Broker", "Dependent", "Estate", "Physician", "Policyholder", "Vendor", "Policyholder Contact",
                "Policyholder Eligibility Contact", "Policyholder Subgroup", "Power Of Attorney");
        List<WebElement> radioButton = driver.findElements(By.xpath("//div/span[@class='slds-form-element__label']"));
        for (String expectedvalue : expectedOptions) {
            boolean found = false;
            for (WebElement radio : radioButton) {
                String value = radio.getText();
                if (expectedvalue.equalsIgnoreCase(value)) {
                    System.out.println("rvalue --> " + value + " | expectedvalue --> " + expectedvalue);
                    found = true;
                    break;
                }
            }
            if (found) {
                System.out.println("Found radio option: " + expectedvalue);
            } else {
                System.out.println("Missing radio option: " + expectedvalue);
                Assert.assertTrue(found, "Missing radio option: " + expectedvalue);
            }
        }
    }

