            base.Common.writeconsule(sc, "TCID: " + tcid + " TC Name: " + tcname);
        //-----------------------------------
        String prodname = (dataMap.get(rownumber).get("ProdName").trim());
        String custFilename = Common.getProductdatafile(prodname);
        String Search_PaymentNo = base.Common.readPropertFile(custFilename, Common.convertKeyWithPrefix("Payment_No", tcid));
        System.out.println("PaymentNo--->" + Search_PaymentNo);
        if (Search_PaymentNo == null || Search_PaymentNo.trim().equalsIgnoreCase("")) {
            throw new Exception("Payment Number is NOT found in property file");
        }
        String Claim_No = base.Common.readPropertFile(custFilename, Common.convertKeyWithPrefix("ClaimNo", tcid));
        if (Claim_No == null || Claim_No.equalsIgnoreCase("")) {
            throw new Exception("Calim ID [" + Claim_No + "] NOT found in property file");
        }
        //        Hooks.message = Hooks.message + "Payment Number [" + Search_PaymentNo + "] \n";
