    @And("^Search Payment And Verify PaymentMethod Is (.*) And AdviceToPay Is (.*) (\\d+)$")
    public void SearchPaymentAndVeriyPaymentMethod(String pmt, String AdvPay, int rownumber) throws Exception {
        System.out.println("\n[--- Start Step ---]");
        Hooks.iterationID = rownumber;
        System.out.println("[Step Iteration# " + rownumber + " ]");
        //------------------------------------
        tcid = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCID") : "");
        tcname = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCName") : "");
        if (tcid != null && !tcid.trim().equalsIgnoreCase(""))
            base.Common.writeconsule(sc, "TCID: " + tcid + " TC Name: " + tcname);
        //-----------------------------------
        String prodname = (dataMap.get(rownumber).get("ProdName").trim());
        String custFilename = Common.getProductdatafile(prodname);
        String Search_PaymentNo = base.Common.readPropertFile(custFilename, Common.convertKeyWithPrefix("Payment_No", tcid));
        System.out.println("PaymentNo--->" + Search_PaymentNo);
        Hooks.message = Hooks.message + "Payment Number [" + Search_PaymentNo + "] \n";
        if (Search_PaymentNo == null || Search_PaymentNo.trim().equalsIgnoreCase("")) {
            throw new Exception("Payment Number [" + Search_PaymentNo + "] NOT found in property file");
        }
        cp.searchPayment(Search_PaymentNo);
        if (AdvPay.equalsIgnoreCase("Yes")) {
            base.Common.waitHighlightAndClick(driver, cp.Edit_btn, sc, "Payment Edit Button", 20, 2);
            Thread.sleep(1000);
            base.Common.scrollandhighLighterMethod(driver, cp.AdviceToPayChkbox);
            if (!base.Common.isElementSelected(driver, By.xpath("//span[text()='Advice to Pay']/../..//div//input[@name='cve__AdviceToPay__c']"), sc, "Advice to Pay", 5)) {
                base.Common.Click(driver, By.xpath("//span[text()='Advice to Pay']/../..//div//input[@name='cve__AdviceToPay__c']"), sc, "Advice to Pay Checkbox", false, true, true, false, 4, 1);
            }
            base.Common.waitHighlightAndClick(driver, cp.SavePayment_btn, 20, 2);
        } else if (AdvPay.equalsIgnoreCase("No")) {
            base.Common.writeconsule(sc, "Advice to Pay Selection Not required");
        }
        base.Common.scrollandhighLighterMethod(driver, cp.PaymentMethod_txt);
        String acctPmtMethod = cp.PaymentMethod_txt.getText().trim().toUpperCase();
        Hooks.message = Hooks.message + "Payment Method [" + acctPmtMethod + "] \n";
        if (pmt.equalsIgnoreCase("Check")) {
            Assert.assertEquals(acctPmtMethod, "Check".trim().toUpperCase());
        } else if (pmt.equalsIgnoreCase("EFT")) {
            Assert.assertEquals(acctPmtMethod, "EFT".trim().toUpperCase());
        }
        base.Common.takeScreenshot(sc, driver, "Payments");
    }

