        tcid = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCID") : "");
        tcname = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCName") : "");
        if (tcid != null && !tcid.trim().equalsIgnoreCase(""))
            base.Common.writeconsule(sc, "[ TCID: " + tcid + " TCName: " + tcname + "]");
        //-----------------------------------
        waitForPageLoaded(driver, 30);// 30);
        driver.switchTo().parentFrame();
        String prodname = (dataMap.get(rownumber).get("ProdName").trim());
        String custFilename = Common.getProductdatafile(prodname);
        String EIS_PACSCustName = base.Common.readPropertFile(custFilename, Common.convertKeyWithPrefix("PACSCustName", tcid));
        //        EIS_PACSCustName.trim().toUpperCase();
        System.out.println("PolicyCutName-->" + EIS_PACSCustName);
        String prodName = prodname;
        if (prodName.trim().equalsIgnoreCase("HI")) {
            prodName = "VHI";
        } else if (prodName.trim().equalsIgnoreCase("CI")) {
            prodName = "VCI";
        } else if (prodName.trim().equalsIgnoreCase("AC")) {
            prodName = "VAI";
        }
        String EIS_PolicyID = "";
        if (FeatureDriver.testPlan.contains("e2e")) {
            EIS_PolicyID = base.Common.readPropertFile(custFilename, Common.convertKeyWithPrefix("QuoteID", tcid));
            System.out.println("QuoteID-->" + EIS_PolicyID);
            if (EIS_PolicyID == null || EIS_PolicyID.equalsIgnoreCase("")) {
                EIS_PolicyID = base.Common.readPropertFile(custFilename, Common.convertKeyWithPrefix("Policy_ID", tcid));
                System.out.println("Policy_ID-->" + EIS_PolicyID);
            }
        } else {
            EIS_PolicyID = base.Common.readPropertFile(custFilename, Common.convertKeyWithPrefix("Policy_ID", tcid));
            System.out.println("Policy_ID-->" + EIS_PolicyID);
        }
        if (EIS_PolicyID == null || EIS_PolicyID.equalsIgnoreCase("")) {
            throw new Exception("Policy ID [" + EIS_PolicyID + "] NOT found in property file");
        }
        String expEffDate = dataMap.get(rownumber).get("Eff_Date");
        String expRSoOption = dataMap.get(rownumber).get("RSO_Option");
        String expUnderWriting_Comp = dataMap.get(rownumber).get("UnderWriting_Comp").trim().toUpperCase();
        String EIS_situs = base.Common.readPropertFile(custFilename, Common.convertKeyWithPrefix("EISsitusState", tcid));
        System.out.println("policy Situs--->" + EIS_situs);
        String accpolicyversion = "637286157";
        String expMatrixAdmin = dataMap.get(rownumber).get("MatrixAdmin").trim().toUpperCase();
        String expPolicyStatus = dataMap.get(rownumber).get("PolicyStatus");
        System.out.println("policyStatue-->" + expPolicyStatus);
        String grpName = cp.GroupName_lbl.getText();
        String prdname = cp.Product_lbl.getText().trim().toUpperCase();
        String plno = cp.detailsscreenPolicyNo_lbl.getText();
        String accteffdate = cp.EffDate_lbl.getText();
        String salesoffice = cp.Salesoffice_lbl.getText();
        String accLob = cp.LineofBusiness.getText();
        String accSitus = cp.Situs_lbl.getText();
        String PolicyStatusCodeEIS = base.Common.waitAndGetText(driver, cp.PolicyStatusCodeEIS_lbl, sc, "PolicyStatusCodeEIS", 20, 2);
        String errormsg = "";
        if (EIS_PolicyID.equalsIgnoreCase(plno)) {
            Hooks.message = Hooks.message + "EIS Policy No Verified --> " + "EIS_PolicyID: [" + EIS_PolicyID + "] " + "\n";
        } else {
            errormsg = errormsg + " EIS Policy No Verified [FAIL] " + "EIS_PolicyID: [" + EIS_PolicyID + "]  Actual: [" + plno + "]\n";
        }
        if (prodName.equalsIgnoreCase(accLob)) {
            Hooks.message = Hooks.message + "EIS Agent Data Verified --> " + "prodName: [" + prodName + "] " + "\n";
        } else {
            errormsg = errormsg + " EIS Policy No Verified [FAIL] " + "prodName: [" + prodName + "]  Actual: [" + accLob + "]\n";
        }
        if (salesoffice.contains("BOS")) {
            Hooks.message = Hooks.message + "EIS and CV adminBy Verified --> " + "salesoffice: [" + accSitus + "] " + "\n";
        } else {
            errormsg = errormsg + "ESI and CV adminBy Verified [FAIL] " + "salesoffice: [" + accSitus + "] " + "\n";
        }
        if (!errormsg.trim().equalsIgnoreCase("")) {
            System.out.println("ErrorMessage-->" + errormsg);
            sc.write(errormsg);
            throw new Exception(errormsg);
        }
