    @And("^Verify word Null anywhere in Benefits Coverages (\\d+)$")
    public void VerifywordNullanywhereinBenefitsCoverages(int rownumber) throws Exception {
        System.out.println("\n[--- Start Step ---]");
        Hooks.iterationID = rownumber;
        System.out.println("[Step Iteration# " + rownumber + " ]");
        //rownumber = rownumber - 1;
        //------------------------------------
        tcid = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCID") : "");
        tcname = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCName") : "");
        if (tcid != null && !tcid.trim().equalsIgnoreCase(""))
            base.Common.writeconsule(sc, "[ TCID: " + tcid + " TCName: " + tcname + "]");
        //-----------------------------------
        waitForPageLoaded(driver, 30);// 30);
        driver.switchTo().parentFrame();
        String prodname = (dataMap.get(rownumber).get("ProdName").trim());
        String custFilename = Common.getProductdatafile(prodname);
        String EIS_PACSCustName = base.Common.readPropertFile(custFilename, Common.convertKeyWithPrefix("PACSCustName", tcid));
        //        EIS_PACSCustName.trim().toUpperCase();
        System.out.println("PolicyCutName-->" + EIS_PACSCustName);
        cp.VerifyEISBenefitDataInCVBenefitDetailsScreen1();
        if (Config.ENV.equalsIgnoreCase("preprod")) {
            base.Common.sleep(4000);
            int noRelatedcount = pl.RelatedList_btn.size();
            System.out.println("No of Related Button-->" + noRelatedcount);
            if (noRelatedcount != 0) {
                int lastelement = noRelatedcount - 1;
                System.out.println("No of Related Button Clicked-->" + noRelatedcount);
                pl.RelatedList_btn.get(lastelement).click();
            }
        } else {
            base.Common.waitHighlightAndClickNoscroll(driver, cp.Coverages_lnk, sc, "Coverage link", 20, 2);
        }
        base.Common.highLighterMethod(driver, cp.CoverageValues_lbl);
        Assert.assertFalse(cp.CoverageValues_lbl.getText().contains("null"), "Coverages are not having Null");
        base.Common.takeScreenshot(sc, driver, "EIS Data in CV Policy Search Screen");
    }

