    @And("^Create New Contacts (\\d+)$")
    public void createNewContacts(int rownumber) throws Exception {
        uniqueContN = "";
        Hooks.iterationID = rownumber;
        System.out.println("[Step Iteration# " + rownumber + " ]");
        //------------------------------------
        tcid = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCID") : "");
        tcname = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCName") : "");
        if (tcid != null && !tcid.trim().equalsIgnoreCase(""))
            base.Common.writeconsule(sc, "[ TCID: " + tcid + " TCName: " + tcname + "]");
        //--------------------------------------------------
        base.Common.sleep(4000);
        String prodname = dataMap.get(rownumber).get("ProdName").trim();
        String custFilename = cv.Common.Common.getProductdatafile(prodname);
        System.out.println("Contactname--> " + prodname);
        String eisPolicyHodlerName = base.Common.readPropertFile(custFilename, Common.convertKeyWithPrefix("EISPolicyHodler", tcid));
        base.Common.writeconsule(sc, "eisPolicyHodlerName-->" + eisPolicyHodlerName);
        Random randomGenerator = new Random();
        int randomInt = randomGenerator.nextInt(8888);
        int randomInt2 = randomGenerator.nextInt(9999);
        String SSN1st = String.format("%03d", randomGenerator.nextInt(999));
        String SSN2nd = String.format("%02d", randomGenerator.nextInt(99));
        String SSN3rd = String.format("%04d", randomGenerator.nextInt(9999));
        String conttype = dataMap.get(rownumber).get("Contact_Type");
        if (conttype.equalsIgnoreCase("emp")) {
            base.Common.sleep(5000);
            base.Common.waitHighlightAndClick(driver, cs.ContactTypeEmp_radio, sc, "EmployeeContact", 20, 2);
        } else if (conttype.equalsIgnoreCase("Physician")) {
            base.Common.waitHighlightAndClick(driver, cs.Physician_radio, sc, "Physician_radio", 20, 2);
        } else {
            base.Common.waitHighlightAndClick(driver, cs.ContactTypeProvider_radio, sc, "ProviderContact", 20, 2);
        }
        String contGender = dataMap.get(rownumber).get("Gender");
        base.Common.writeconsule(sc, "Gender Select-->" + contGender);
        cs.CreateContact(dataMap.get(rownumber).get("Saluation"), dataMap.get(rownumber).get("ContactFname") + randomInt, dataMap.get(rownumber).get("ContactLname") + randomInt2, SSN1st + "-" + SSN2nd + "-" + SSN3rd, contGender, eisPolicyHodlerName,
                //                cp.getPH(dataMap.get(rownumber).get("ProdName").trim()),
                dataMap.get(rownumber).get("MailingCountry"), dataMap.get(rownumber).get("MailingStree"), dataMap.get(rownumber).get("MailingCiti"), dataMap.get(rownumber).get("MailingState"), dataMap.get(rownumber).get("MailingZip"), dataMap.get(rownumber).get("BrithDate"), dataMap.get(rownumber).get("DateofHair"), dataMap.get(rownumber).get("WorkState"), dataMap.get(rownumber).get("BankAccount_Type"), dataMap.get(rownumber).get("Commination"), dataMap.get(rownumber).get("PMTMethod"), dataMap.get(rownumber).get("PreferredLanguage"));
        base.Common.waitUntilRefreshedAndClickable(driver, cs.Contact_lbl, 20, 2);
        base.Common.highLighterMethod(driver, cs.Contact_lbl);
        String ContactDetails = base.Common.waitAndGetText(driver, cs.Contact_lbl, sc, "Contact Name", 20, 2);
        //        cs.Contact_lbl.getText();
        System.out.println("ContactNameWithPrefix--->" + ContactDetails);
        String[] arrOfStr = ContactDetails.split("Mr.");
        String AfterSpiltContactNamesecoundHalf = arrOfStr[1];
        sc.write("contactArry1-->" + AfterSpiltContactNamesecoundHalf);
        String prodname1 = dataMap.get(rownumber).get("ProdName").trim();
        String custFilename1 = cv.Common.Common.getProductdatafile(prodname1);
        System.out.println("Contactname--> " + custFilename1);
//        base.Common.writePropertFile(custFilename1, "Contact", AfterSpiltContactNamesecoundHalf.trim());
        base.Common.writePropertFile(custFilename1, Common.convertKeyWithPrefix("Contact", tcid), AfterSpiltContactNamesecoundHalf.trim());
        //        String ExpectedCN = base.Common.readPropertFile(custFilename1, "Contact").trim().toUpperCase();
        String ExpectedCN = base.Common.readPropertFile(custFilename1, Common.convertKeyWithPrefix("Contact", tcid));
        System.out.println("Contactname--> " + ExpectedCN);
        System.out.println("[--- End ]");
        base.Common.takeScreenshot(sc, driver, "Contacts");
        base.Common.writeconsule(sc, "Contact -->" + AfterSpiltContactNamesecoundHalf);
        Hooks.message = Hooks.message + "Contact Created Successfully  --> Contact: [" + AfterSpiltContactNamesecoundHalf + "] " + "\n";
        Thread.sleep(5000);
        if (dataMap.get(rownumber).get("ProdName").trim().equalsIgnoreCase("STD")) {
            driver.navigate().refresh();
            Thread.sleep(15000);
            int EditButtonCount = cp.Edit_btn_list.size();
            int listofshowmore = cp.showmoreList_lnk.size();
            System.out.println("No of EDIT Button-->" + EditButtonCount);
            if (EditButtonCount != 0) {
                sc.write("Edit element present count -->" + EditButtonCount);
                base.Common.Click(driver, cp.Edit_btn, sc, "showmore_lnk", false, false, true, false, 10, 4);
            } else if (listofshowmore != 0) {
                sc.write("Show More drop down element present count -->" + listofshowmore);
                base.Common.Click(driver, cp.showmore_lnk, sc, "showmore_lnk", false, false, true, false, 10, 4);
                base.Common.Click(driver, cp.EditContact_lnk, sc, "EditContact_lnk", false, false, true, false, 10, 4);
            }
            int HWcont = cs.HoursWorked_inputlist.size();
            if (HWcont > 0) {
                base.Common.EnterData(driver, cs.HoursWorked_input, "2000", sc, "HoursWorked_input", false, false, false, true, false, 20, 2);
            }
            int BPCount = cs.BonusPeriod_dropdownIconlst.size();
            if (BPCount > 0) {
                base.Common.waitHighlightAndClick(driver, cs.BonusPeriod_dropdownIcon, sc, "BonusPeriod_dropdownIcon", 30, 2);
                base.Common.Click(driver, By.xpath("//lightning-base-combobox-item//span[text()='Month']"), sc, "", false, false, true, false, 4, 2);
                Thread.sleep(2000);
            }
            int EPDcount = cs.EarningsPeriod_dropdownIconlst.size();
            if (EPDcount > 0) {
                base.Common.waitHighlightAndClick(driver, cs.EarningsPeriod_dropdownIcon, sc, "EarningsPeriod Drop Down", 30, 2);
                base.Common.Click(driver, By.xpath("(//lightning-base-combobox-item//span[text()='Month'])[2]"), sc, "", false, false, true, false, 4, 2);
                base.Common.EnterData(driver, cs.Earnings_input, "4000", sc, "Earnings_input", false, false, false, true, false, 20, 2);
            }
            base.Common.Click(driver, cp.ClaimSave_button, sc, "Save_button", false, false, true, false, 10, 4);
        }
    }

