    @And("^Verify Duplicate Claim Message on BCbanner (\\d+)$")
    public void VerifyDuplicateClaimMessageonBCbanner(int rownumber) throws Exception {
        System.out.println("\n[--- Start Step ---]");
        Hooks.iterationID = rownumber;
        System.out.println("[Step Iteration# " + rownumber + " ]");
        //------------------------------------
        tcid = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCID") : "");
        tcname = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCName") : "");
        if (tcid != null && !tcid.trim().equalsIgnoreCase(""))
            base.Common.writeconsule(sc, "[ TCID: " + tcid + " TCName: " + tcname + "]");
        //-----------------------------------
        String prodname = (dataMap.get(rownumber).get("ProdName").trim());
        String custFilename = Common.getProductdatafile(prodname);
        HashMap dataHashMap = dataMap.get(rownumber);
        String duplicateCliam = "";
        String xpath = "//c-duplicate-disability-claim-check//b";
        if (dataMap.get(rownumber).get("TCID").equalsIgnoreCase("448298") ||
                dataMap.get(rownumber).get("TCID").equalsIgnoreCase("448309")) {
            List<WebElement> elements = driver.findElements(By.xpath(xpath));
            boolean isNotFound = elements.isEmpty();
            Assert.assertTrue(isNotFound, "Element was found, but it should NOT be present.");
        } else {
            duplicateCliam = base.Common.waitAndGetText(driver, By.xpath("//c-duplicate-disability-claim-check//b"), sc, "", false, true, 5, 2);
            duplicateCliam.trim();
            System.out.println("duplicateCliam-->" + duplicateCliam);
            String ExpDuplicateMsg =
                    ("Possible Duplicate Claim/Benefit Claimed. Similar Claim/Benefit Claimed is exists with same Employee, Policy and Cause.");
            Assert.assertTrue(duplicateCliam.equals(ExpDuplicateMsg.trim()), "Not showing Duplicate msag");
        }
    }

