    @And("^Create New Absence Claim1 (\\d+)$")
    public void CreateNewAbsenceClaimCreation1(int rownumber) throws Exception {
        Hooks.iterationID = rownumber;
        System.out.println("[Step Iteration# " + rownumber + " ]");
        //------------------------------------
        tcid = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCID") : "");
        tcname = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCName") : "");
        if (tcid != null && !tcid.trim().equalsIgnoreCase(""))
            base.Common.writeconsule(sc, "[ TCID: " + tcid + " TCName: " + tcname + "]");
        //--------------------------------------------------
        String prodname = dataMap.get(rownumber).get("ProdName").trim();
        String custFilename = cv.Common.Common.getProductdatafile(prodname);
        System.out.println("Product Name--> " + prodname);
        String EISPolicyNO = base.Common.readPropertFile(custFilename, Common.convertKeyWithPrefix("Policy_ID", tcid));
        sc.write("EIS Policy ID: " + EISPolicyNO);
        Hooks.message = Hooks.message + "EIS Policy ID: " + EISPolicyNO + "\n";
        if (EISPolicyNO == null || EISPolicyNO.equalsIgnoreCase("")) {
            throw new Exception("Policy ID NOT found in the property file: " + custFilename);
        }
        String dateoflost = (new SimpleDateFormat("M/dd/yyyy")).format(new Date());
        System.out.println("DateoflossCurrentDte ===>" + dateoflost);
        String ContactName = base.Common.readPropertFile(custFilename, Common.convertKeyWithPrefix("Contact", tcid));
        /*==========================================================*/
        cp.CreateNewNewAbsenceClaim(ContactName);
        /*==========================================================*/
    }

