    @And("^Verify Document History Is Showing (.*) for (.*) claims (\\d+)$")
    public void checkDocumentHistory(String DeliveryType, String filedType, int rownumber) throws Exception {
        System.out.println("\n[--- Start Step ---]");
        Hooks.iterationID = rownumber;
        System.out.println("[Step Iteration# " + rownumber + " ]");
        //------------------------------------
        tcid = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCID") : "");
        tcname = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCName") : "");
        if (tcid != null && !tcid.trim().equalsIgnoreCase(""))
            base.Common.writeconsule(sc, "[ TCID: " + tcid + " TCName: " + tcname + "]");
        //-----------------------------------
        Thread.sleep(3000);
        driver.navigate().refresh();
        Thread.sleep(10000);
        List<WebElement> headers = driver.findElements(By.xpath("//table//tr[@data-row-key-value='HEADER']//div[@class='slds-has-button-menu']/span/span"));
        for (WebElement header : headers) {
            System.out.println("Header text: " + header.getText().trim());
        }
        List<WebElement> headerSpans = driver.findElements(By.xpath("//table//tr[@data-row-key-value='HEADER']//div[@class='slds-has-button-menu']/span/span"));
        int columnIndex = -1;
        for (int i = 0; i < headerSpans.size(); i++) {
            String headerText = headerSpans.get(i).getText().trim();
            System.out.println("Headerindex: " + headerText);
            if (headerText.equals("New Value")) {
                columnIndex = i + 1;
                System.out.println("columnIndex: " + columnIndex);
                break;
            }
        }
        List<String> cellTexts = new ArrayList<>();
        List<WebElement> columnCells = driver.findElements(By.xpath("//table//tr/td[" + columnIndex + "]"));
        for (WebElement cell : columnCells) {
            String cText = cell.getText().trim();
            System.out.println("Cellvalue --> " + cText);
            cellTexts.add(cText);
        }
        System.out.println("cellTexts --> " + cellTexts);
        if (DeliveryType.equalsIgnoreCase("Print")) {
            Assert.assertTrue(cellTexts.contains("Print success"), "Expected value Print Success not found in column cells");
        } else if (DeliveryType.equalsIgnoreCase("Fax")) {
            Assert.assertTrue(cellTexts.contains("None success"), "Expected value  None success not found in column cells");
        } else if (DeliveryType.equalsIgnoreCase("eServices")) {
            Assert.assertTrue(cellTexts.contains("EService success"), "Expected value  EService success not found in column cells");
        } else if (DeliveryType.equalsIgnoreCase("Finalized")) {
            Assert.assertTrue(cellTexts.contains("Finalized"), "Expected value  Finalized not found in column cells");
        } else if (DeliveryType.equalsIgnoreCase("Email")) {
            Assert.assertTrue(cellTexts.contains("Email success"), "Expected value  Email success not found in column cells");
        } else if (DeliveryType.equalsIgnoreCase("RSLIprinter")) {
            Assert.assertTrue(cellTexts.contains("RSLI printer"), "Expected value  RSLI printer not found in column cells");
        }
    }

