    @And("^Verify (.*) Absences Claim Is (.*) (\\d+)$")
    public void verifyAbsencesNotCreated(String claimType, String isAdded, int rownumber) throws Exception {
        System.out.println("\n[--- Start Step ---]");
        Hooks.iterationID = rownumber;
        System.out.println("[Step Iteration# " + rownumber + " ]");
        //------------------------------------
        tcid = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCID") : "");
        tcname = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCName") : "");
        if (tcid != null && !tcid.trim().equalsIgnoreCase(""))
            base.Common.writeconsule(sc, "[ TCID: " + tcid + " TCName: " + tcname + "]");
        //-----------------------------------
        int countpAbsenceClaims = driver.findElements(By.xpath("//h2[text()='Related List Quick Links']/../..//li//div//slot[contains(text(),'Absence Claims')]/ancestor::a")).size();
        System.out.println("countpAbsenceClaims-->" + countpAbsenceClaims);
        if (isAdded.equalsIgnoreCase("NOT-Added")) {
            if (countpAbsenceClaims > 0) {
                String NoAbsenceClaims = base.Common.waitAndGetText(driver, By.xpath("//h2[text()='Related List Quick Links']/../..//li//div//slot[contains(text(),'Absence Claims')]/ancestor::a//slot"), sc, "", false, true, 5, 2);
                System.out.println("NoAbsenceClaims-->" + NoAbsenceClaims);
                Assert.assertEquals(NoAbsenceClaims, "Absence Claims (0)", "AbsenceClaimCreatedForNonPaidPolic");
            } else {
                base.Common.Click(driver, By.xpath("//h2[text()='Related List Quick Links']/ancestor::lst-related-list-quick-links-container//a[contains(text(),'Show All')]"), sc, "Show All link", false, false, true, false, 10, 4);
                String NoAbsenceClaims = base.Common.waitAndGetText(driver, By.xpath("//h2[text()='Related List Quick Links']/../..//li//div//slot[contains(text(),'Absence Claims')]/ancestor::a//slot"), sc, "", false, true, 5, 2);
                System.out.println("NoAbsenceClaims-->" + NoAbsenceClaims);
                Assert.assertEquals(NoAbsenceClaims, "Absence Claims (0)", "AbsenceClaimCreatedForNonPaidPolic");
            }
        } else if (isAdded.equalsIgnoreCase("Added")) {
            if (countpAbsenceClaims > 0) {
                String NoAbsenceClaims = base.Common.waitAndGetText(driver, By.xpath("//h2[text()='Related List Quick Links']/../..//li//div//slot[contains(text(),'Absence Claims')]/ancestor::a//slot"), sc, "", false, true, 5, 2);
                System.out.println("NoAbsenceClaims-->" + NoAbsenceClaims);
            } else {
                base.Common.Click(driver, By.xpath("//h2[text()='Related List Quick Links']/ancestor::lst-related-list-quick-links-container//a[contains(text(),'Show All')]"), sc, "Show All link", false, false, true, false, 10, 4);
                String NoAbsenceClaims = base.Common.waitAndGetText(driver, By.xpath("//h2[text()='Related List Quick Links']/../..//li//div//slot[contains(text(),'Absence Claims')]/ancestor::a//slot"), sc, "", false, true, 5, 2);
                System.out.println("NoAbsenceClaims-->" + NoAbsenceClaims);
                Assert.assertEquals(NoAbsenceClaims, "Absence Claims (0)", "AbsenceClaimCreatedForNonPaidPolic");
            }
        }
    }

