    @And("^Verify Claim Status Is (.*) If BC Status Is (.*) (\\d+)$")
    public void verifyClaimStatusIfBCstatusIs(String ClaimStatus, String BCstatus, int rownumber) throws Exception {
        System.out.println("\n[--- Start Step ---]");
        Hooks.iterationID = rownumber;
        System.out.println("[Step Iteration# " + rownumber + " ]");
        //------------------------------------
        tcid = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCID") : "");
        tcname = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCName") : "");
        if (tcid != null && !tcid.trim().equalsIgnoreCase(""))
            base.Common.writeconsule(sc, "[ TCID: " + tcid + " TCName: " + tcname + "]");
        //-----------------------------------
        Thread.sleep(2000);
        base.Common.pageRefresh(driver);
        Thread.sleep(5000);
        String prodctName = dataMap.get(rownumber).get("ProdName").trim();
        String actClaimStatus = "";
        if (BCstatus.equalsIgnoreCase("Approve")) {
            actClaimStatus = base.Common.waitAndGetText(driver, cp.ClaimStatus, sc, "ClaimStatus", false, true, 5, 2);
            Assert.assertEquals("Open", actClaimStatus, "Not Matching");
        } else if (BCstatus.equalsIgnoreCase("ReOpen")) {
            System.out.println("Check Claim Status If BC Status ReOpen");
            actClaimStatus = base.Common.waitAndGetText(driver, cp.ClaimStatus, sc, "ClaimStatus", false, true, 5, 2);
            Assert.assertEquals("Open", actClaimStatus, "Not Matching");
        } else if (BCstatus.equalsIgnoreCase("AppealWithRecalculation")) {
            actClaimStatus = base.Common.waitAndGetText(driver, cp.ClaimStatus, sc, "ClaimStatus", false, true, 5, 2);
            Assert.assertEquals("Open", actClaimStatus, "Not Matching");
        } else if (BCstatus.equalsIgnoreCase("Pending")) {
            actClaimStatus = base.Common.waitAndGetText(driver, cp.ClaimStatus, sc, "ClaimStatus", false, true, 5, 2);
            Assert.assertEquals("Pending", actClaimStatus, "Not Matching");
        } else if (BCstatus.equalsIgnoreCase("AppealWithAdverseDecision")) {
            actClaimStatus = base.Common.waitAndGetText(driver, cp.ClaimStatus, sc, "ClaimStatus", false, true, 5, 2);
            Assert.assertEquals("Closed", actClaimStatus, "Not Matching");
        } else if (BCstatus.equalsIgnoreCase("Closed")) {
            actClaimStatus = base.Common.waitAndGetText(driver, cp.ClaimStatus, sc, "ClaimStatus", false, true, 5, 2);
            Assert.assertEquals("Closed", actClaimStatus, "Not Matching");
        } else if (BCstatus.equalsIgnoreCase("Appeal")) {
            actClaimStatus = base.Common.waitAndGetText(driver, cp.ClaimStatus, sc, "ClaimStatus", false, true, 5, 2);
            Assert.assertEquals("Open", actClaimStatus, "Not Matching");
        }
    }

