        base.Common.sleep(1000);
        if (Config.ENV.equalsIgnoreCase("PREPROD") || Config.ENV.equalsIgnoreCase("UAT")) {
            cp.ClickCashManagement();
        } else {
            base.Common.scrollandhighLighterMethod(driver, cp.caseManagement_lnk);
            base.Common.focusAndClick(driver, cp.caseManagement_lnk);
        }
        waitForPageLoaded(driver, 30);// 10);
