            base.Common.waitHighlightAndJsClick(driver, cp.BenefitsClaimed_lnk, 10, 2);
            base.Common.sleep(3000);
            sc.write("Click BenifitClaim name link");
            base.Common.waitHighlightAndClick(driver, cp.BenefitsClaimedBenefitCliamName_lnk, 20, 2);
