        base.Common.Click(driver, cp.IndividualEffDate_EditIcon, sc, "IndividualEffDate_EditIcon", true, false, true, false, 10, 2);
        String updateDate = "";
        Date today = new Date();
        SimpleDateFormat dateFormat = new SimpleDateFormat("MM/dd/yyyy");
        int addDays = Integer.parseInt("6");
        Calendar c = Calendar.getInstance();
        c.add(Calendar.DATE, addDays);
        updateDate = (String) (dateFormat.format(c.getTime()));
