        int noframes = iframeElements.size();
        if (noframes == 1) {
            driver.switchTo().frame(0);
        } else if (noframes > 1) {
            driver.switchTo().frame(1);
        }
        Thread.sleep(2000);
        int paymentModeCount = cp.PaymentMode_lst.size();
        if (paymentModeCount > 0) {
            base.Common.Click(driver, cp.PaymentMode_lnk, sc, "PaymentMode", true, true, true, false, 5, 2);
        }
        for (int i = 1; i <= 3; i++) {
            Thread.sleep(1500);
            WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(20));
            JavascriptExecutor js = (JavascriptExecutor) driver;
            wait.until(webDriver -> js.executeScript("return document.readyState").equals("complete"));
            WebElement CPbtn = wait.until(ExpectedConditions.presenceOfElementLocated(By.xpath("//input[@value='Calculate Payments']")));
            js.executeScript("arguments[0].click();", CPbtn);
            base.Common.waitForPageLoaded(driver, 30);
            List<WebElement> BusyIcon = driver.findElements(By.xpath("//td/input[@value='Calculating']"));
            System.out.println("PSFoundelements: " + BusyIcon.size());
            if (BusyIcon.size() > 0) {
                base.Common.waitForPageLoaded(driver, 30);
                if (BusyIcon.size() > 0) {
                    System.out.println("PSFoundelements1: " + BusyIcon.size());
                    System.out.println("BusyIconfound → refreshing page... Attempt: " + i);
                    driver.navigate().refresh();
                    base.Common.acceptAndGetTextIfAlertExist(driver);
                    List<WebElement> iframeElements1 = driver.findElements(cp.iframes);
                    System.out.println("The total number of iframes1 are " + iframeElements1.size());
                    int noframes1 = iframeElements1.size();
                    if (noframes1 == 1) {
                        driver.switchTo().frame(0);
                    } else if (noframes1 > 1) {
                        driver.switchTo().frame(1);
                    }
                    Thread.sleep(2000);
                    System.out.println("ClickAgain");
                }
            } else {
                System.out.println("BusyIcon NOT Found → no refresh needed");
                break;
            }
        }
        base.Common.sleep(5000);
