    public void clickDrpDwnValues(By locator, String value) throws InterruptedException {
        if (!value.equalsIgnoreCase("")) {
            WebElement wbElement = driver.findElement(locator);
            base.Common.highLighterMethod(driver, wbElement);
            wbElement.click();
            Thread.sleep(500);
            WebElement option = driver.findElement(By.xpath("//option[text()='" + value + "']"));
            Thread.sleep(500);
//            base.Common.highLighterMethod(driver,option);
            option.click();
            Thread.sleep(1000);
        }
    }

    @And("^Verify (.*) State Reminder popup text (\\d+)$")
    public void verifyPCReminderpopup(String situsState, int rownumber) throws Exception {
        System.out.println("\n[--- Start Step ---]");
        Hooks.iterationID = rownumber;
        System.out.println("[Step Iteration# " + rownumber + " ]");
        //------------------------------------
        tcid = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCID") : "");
        tcname = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCName") : "");
        if (tcid != null && !tcid.trim().equalsIgnoreCase(""))
            base.Common.writeconsule(sc, "[ TCID: " + tcid + " TCName: " + tcname + "]");
        //------------------------------------
        base.Common.sleep(3000);
        String prodname = (dataMap.get(rownumber).get("ProdName").trim());
        String custFilename = Common.getProductdatafile(prodname);
        base.Common.Click(driver, cp.PaymentCalculation_lnk, sc, "PaymentCalculation_lnk", true, false, false, false, 5, 2);
        Thread.sleep(5000);
        Alert alert = base.Common.isAlertExist(driver);
        if (alert != null) {
            driver.switchTo().alert();
            if (situsState.equalsIgnoreCase("RT")) {
                String msg = alert.getText();
                System.out.println("Alert text: " + msg);
                Assert.assertTrue(msg.contains("The Workstate of the claimant/insured required statutory state offsets (as adjustments) before calculating payments."), "user not getting alert message if address is blank-->" + msg);
            } else if (situsState.equalsIgnoreCase("DC")) {
                String msg = alert.getText();
                System.out.println("Alert text: " + msg);
                Assert.assertTrue(msg.contains("The Workstate of the claimant/insured required statutory state offsets (as adjustments) before calculating payments."), "user not getting alert message if address is blank-->" + msg);
            } else if (situsState.equalsIgnoreCase("PR")) {
                String msg = alert.getText();
                System.out.println("Alert text: " + msg);
                Assert.assertTrue(msg.contains("The Workstate of the claimant/insured required statutory state offsets (as adjustments) before calculating payments."), "user not getting alert message if address is blank-->" + msg);
            } else if (situsState.equalsIgnoreCase("OR")) {
                String msg = alert.getText();
                System.out.println("Alert text: " + msg);
                Assert.assertTrue(msg.contains("The Workstate of the claimant/insured required statutory state offsets (as adjustments) before calculating payments."), "user not getting alert message if address is blank-->" + msg);
            } else if (situsState.equalsIgnoreCase("CO")) {
                String msg = alert.getText();
                System.out.println("Alert text: " + msg);
                Assert.assertTrue(msg.contains("The Workstate of the claimant/insured required statutory state offsets (as adjustments) before calculating payments."), "user not getting alert message if address is blank-->" + msg);
            } else if (situsState.equalsIgnoreCase("MA")) {
                if (alert == null) {
                    boolean isAssetPassed = alert == null;
                    Assert.assertTrue(isAssetPassed, "MAstateNOTgettingalertPopup");
                } else {
                    driver.switchTo().alert();
                    String msg = alert.getText();
                    System.out.println("Alert text: " + msg);
                    Assert.fail("MA-Stategettingalertmessage-->" + msg);
                }
            }
            alert.accept();
        }
    }

