    @And("^Validate the field Number of Days from payment release date (\\d+)$")
    public void validatePaymentReleaseDate(int rownumber) throws Exception {
        System.out.println("\n[--- Start Step ---]");
        Hooks.iterationID = rownumber;
        System.out.println("[Step Iteration# " + rownumber + " ]");
        //------------------------------------
        tcid = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCID") : "");
        tcname = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCName") : "");
        if (tcid != null && !tcid.trim().equalsIgnoreCase(""))
            base.Common.writeconsule(sc, "[ TCID: " + tcid + " TCName: " + tcname + "]");
        //------------------------------------
        String prodname = (dataMap.get(rownumber).get("ProdName").trim());
        String custFilename = Common.getProductdatafile(prodname);
        String PmtReleaseDate = base.Common.readPropertFile(custFilename, Common.convertKeyWithPrefix("PaymentReleaseDate", tcid));
        System.out.println("PmtReleaseDate-->" + PmtReleaseDate);
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("M/d/yyyy");
        LocalDate targetDate = LocalDate.parse(PmtReleaseDate, formatter);
        LocalDate today = LocalDate.now();
        long daysBetween = ChronoUnit.DAYS.between(today, targetDate);
        System.out.println("Daysdifference-->" + daysBetween);
        String ChangeToOriginalData = base.Common.readPropertFile(custFilename,
                Common.convertKeyWithPrefix("NoOfdaysfromPaymentReleaseDate", tcid));
        long expdays = Long.parseLong(ChangeToOriginalData);
        System.out.println("Convertedlongvalue: " + expdays);
        Assert.assertEquals(java.util.Optional.of(daysBetween), java.util.Optional.of(expdays), "0 days should be");
    }

