    @And("^Claim Payment Calculation After New Adjustment (\\d+)$")
    public void CreatePaymentCalculationAfterNewAdjustment(int rownumber) throws Exception {
        System.out.println("\n[--- Start Step ---]");
        Hooks.iterationID = rownumber;
        System.out.println("[Step Iteration# " + rownumber + " ]");
        //------------------------------------
        tcid = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCID") : "");
        tcname = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCName") : "");
        if (tcid != null && !tcid.trim().equalsIgnoreCase(""))
            base.Common.writeconsule(sc, "[ TCID: " + tcid + " TCName: " + tcname + "]");
        //------------------------------------
        base.Common.sleep(3000);
        String prodname = (dataMap.get(rownumber).get("ProdName").trim());
        String custFilename = Common.getProductdatafile(prodname);
        String benefitClaim = base.Common.readPropertFile(custFilename, Common.convertKeyWithPrefix("BenefitClaimID", tcid));
        if (benefitClaim == null || benefitClaim.equalsIgnoreCase("")) {
            throw new Exception("Benefit Claim Number NOT found in property file: " + custFilename);
        }
        base.Common.takeScreenshot(sc, driver, "Screen-Payment Calculation Clicked in Payment Spec page");
        base.Common.pageRefresh(driver);
        base.Common.sleep(2000);
        List<WebElement> iframeElements = driver.findElements(cp.iframes);
        System.out.println("The total number of iframes are " + iframeElements.size());
        int noframes = iframeElements.size();
        if (noframes == 1) {
            System.out.println("Switch frame 0");
            driver.switchTo().frame(0);
        } else if (noframes > 1) {
            System.out.println("Switch frame 1");
            driver.switchTo().frame(1);
        }
        base.Common.sleep(2000);
        base.Common.highLighterMethod(driver, cp.Factors_lbl);
        int payeeAddLinkCount = cp.AddPayee_linklist.size();
        if (payeeAddLinkCount > 0) {
            base.Common.Click(driver, cp.AddPayee_link, sc, "AddPayee_link", true, true, true, false, 5, 2);
        }
        base.Common.waitForAllElementsVisible(driver, cp.CalculatePayment_btnlist, 10, 2);
        int calculatepaymentcount = cp.CalculatePayment_btnlist.size();
        System.out.println("No of CalculatePayment Button-->" + calculatepaymentcount);
        if (calculatepaymentcount != 0) {
            int lastelementofcalculatepayment = calculatepaymentcount - 1;
            System.out.println("Selected Payment Button index-->" + lastelementofcalculatepayment);
            base.Common.highLighterMethod(driver, cp.CalculatePayment_btnlist.get(lastelementofcalculatepayment));
            if (cp.CalculatePayment_btnlist.get(lastelementofcalculatepayment).isEnabled()) {
                cp.CalculatePayment_btnlist.get(lastelementofcalculatepayment).click();
                waitForPageLoaded(driver, 30);
                base.Common.writeconsule(sc, "Calculate Payment button clicked");
            } else {
                throw new Exception("Calculate Payments button in payment screen is DISABLED, Benefit Claim may be in Denied or NOT approved status");
            }
        }
        base.Common.sleep(5000);
        base.Common.waitForAllElementsVisible(driver, cp.Paymentlist_chkbox, 10, 2);
        base.Common.scrollandhighLighterMethod(driver, cp.Payment_chkbox);
        int NoPayments = cp.Paymentlist_chkbox.size();
        System.out.println("No of Payments checkbox-->" + NoPayments);
        if (NoPayments != 0) {
            int lastcheckelement = NoPayments - 1;
            System.out.println("No of Related Button Clicked-->" + NoPayments);
            cp.Paymentlist_chkbox.get(lastcheckelement).click();
            base.Common.writeconsule(sc, "Payment record check box selected");
            base.Common.sleep(2000);
        }
        base.Common.takeScreenshot(sc, driver, "Payment Number record check box selected");
        String paymentvalue = "";
        try {
            paymentvalue = cp.paymentname_lnk.getText();
        } catch (Exception e) {
            base.Common.writeconsule(sc, "Exception: Unable to read payment number link text");
        }
        Hooks.message = Hooks.message + " Calculate Payment Page --> PaymentNo: [" + paymentvalue + "] \n";
        base.Common.sleep(2000);
        base.Common.scrollandhighLighterMethod(driver, cp.Payment_chkbox);
        base.Common.waitHighlightAndJsClick(driver, cp.Payment_chkbox, sc, "Paymentlist_chkbox", 30, 2);
        base.Common.highLighterMethod(driver, cp.SubmitApprove_btn);
        cp.SubmitApprove_btn.click();
        base.Common.sleep(10000);
        base.Common.acceptAndGetTextIfAlertExist(driver);
        base.Common.takeScreenshot(sc, driver, "Payment Completed");
        base.Common.writePropertFile(custFilename, Common.convertKeyWithPrefix("Payment_No", tcid), paymentvalue);
        base.Common.writeconsule(sc, "PaymentNo-->" + paymentvalue);
        Hooks.message = Hooks.message + "Payment Page --> PaymentNo: [" + paymentvalue + "] \n";
    }

