    @And("^Verify Claim Intake In Eligibility (.*) Update (\\d+)$")
    public void verifyClaimIntakeInEligibility(String afterbefore, int rownumber) throws
            AWTException, InterruptedException, IOException {
        System.out.println("\n[--- Start Step ---]");
        Hooks.iterationID = rownumber;
        System.out.println("[Step Iteration# " + rownumber + " ]");
        String prodname = (dataMap.get(rownumber).get("ProdName").trim());
        String custFilename = Common.getProductdatafile(prodname);
        //------------------------------------
        List<WebElement> iframeElements = driver.findElements(cp.iframes);
        sc.write("The total number of iframes are " + iframeElements.size());
        int noframes = iframeElements.size();
        if (noframes == 1) {
            sc.write("Switch frame 0");
            driver.switchTo().frame(0);
        } else if (noframes > 1) {
            sc.write("Switch frame 1");
            driver.switchTo().frame(1);
        }
        Thread.sleep(4000);
        sc.write("Click Eligibility link");
        String ExpDateofLoss = "";
        base.Common.waitAndClick(driver, cp.Eligibility_lnk, sc, "Eligibility Link", false, false, true, 4, 2);
        base.Common.sleep(2000);
        String eligibilityTxt = base.Common.waitAndGetText(driver, cp.EligibilityResults_txt, sc, "EligibilityResults_tx", 4, 2);
        System.out.println("eligibilityTxt-->" + eligibilityTxt);
        if (afterbefore.equalsIgnoreCase("Before")) {
            ExpDateofLoss = base.Common.readPropertFile(custFilename, Common.convertKeyWithPrefix("DateofLossClaimCreation", tcid));
            Assert.assertTrue(eligibilityTxt.contains(ExpDateofLoss), "DateOfLoss NOT Matching Before Update");
        } else if (afterbefore.equalsIgnoreCase("After")) {
            ExpDateofLoss = dataMap.get(rownumber).get("UpdateDateOfLoss");
            Assert.assertTrue(eligibilityTxt.contains(ExpDateofLoss), "DateOfLoss NOT Matching After Update");
        }
    }

