    @And("^Generate New Document Letter for (.*) (\\d+)$")   //Generate New Document Letter for
    public void CreateNewDocumentLetter(String letterName, int rownumber) throws Exception {
        Hooks.iterationID = rownumber;
        //------------------------------------
        tcid = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCID") : "");
        tcname = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCName") : "");
        if (tcid != null && !tcid.trim().equalsIgnoreCase(""))
            base.Common.writeconsule(sc, "[ TCID: " + tcid + " TCName: " + tcname + "]");
        //------------------------------------
        HashMap dataHashMap = dataMap.get(rownumber);
        CreateNewDocumentLettersAndClickGenerateLetterPreview(letterName, rownumber, dataHashMap);
        cnd.CompleteDocumentCreationFromClickLetterReviewed(dataMap.get(rownumber).get("ChenboxType"), dataHashMap);
        boolean LetterName2columnexist = base.Common.checkColumnExistInDataSheet(dataMap, "Letter_Name2");
        if (LetterName2columnexist && !dataMap.get(rownumber).get("Letter_Name2").equalsIgnoreCase("")) {
            driver.navigate().refresh();
            Thread.sleep(2000);
            CreateNewDocumentLettersAndClickGenerateLetterPreview1(dataMap.get(rownumber).get("Letter_Name2"), rownumber);
            cnd.CompleteDocumentCreationFromClickLetterReviewed(dataMap.get(rownumber).get("ChenboxType"), dataHashMap);
        }
    }

