    @And("^Verify Created a Bundle for the option (.*) (\\d+)$")
    public void verifyBundleOption(String DT, int rownumber) throws Exception {
        System.out.println("\n[--- Start Step ---]");
        Hooks.iterationID = rownumber;
        System.out.println("[Step Iteration# " + rownumber + " ]");
        //------------------------------------
        tcid = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCID") : "");
        tcname = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCName") : "");
        if (tcid != null && !tcid.trim().equalsIgnoreCase(""))
            base.Common.writeconsule(sc, "[ TCID: " + tcid + " TCName: " + tcname + "]");
        //-----------------------------------
        Thread.sleep(500);
        String DTtype = "";
        String Status = "";
        DTtype = base.Common.waitAndGetText(driver,
                By.xpath("//records-record-layout-item[@field-label='Delivery Method']//lightning-formatted-text"),
                sc, "DT", false, true, 4, 2);
        Status = base.Common.waitAndGetText(driver,
                By.xpath("//records-record-layout-item[@field-label='Status']//lightning-formatted-text"),
                sc, "status", false, true, 4, 2);
        if (DT.equalsIgnoreCase("Email")) {
            Assert.assertEquals(DTtype, "Email", "Not Same");
        }
        if (DT.equalsIgnoreCase("Print")) {
            Assert.assertEquals(Status.toLowerCase(), "Print success".toLowerCase(), "Not Same");
        }
    }

