    @Given("^Search Claim And Update ClaimReleation (\\d+)$")
    public void searchClaimAndUpdateClaimReleation(int rownumber) throws Exception {
        System.out.println("\n[--- Start Step ---]");
        Hooks.iterationID = rownumber;
        System.out.println("[Step Iteration# " + rownumber + " ]");
        //rownumber = rownumber - 1;
        //------------------------------------
        tcid = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCID") : "");
        tcname = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCName") : "");
        if (tcid != null && !tcid.trim().equalsIgnoreCase(""))
            base.Common.writeconsule(sc, "TCID: " + tcid + " TC Name: " + tcname);
        //-----------------------------------
        String prodname = (dataMap.get(rownumber).get("ProdName").trim());
        String custFilename = Common.getProductdatafile(prodname);
        String ClaimNumber = base.Common.readPropertFile(custFilename, Common.convertKeyWithPrefix("ClaimNo", tcid));
        sc.write("Claim ID from file: " + ClaimNumber);
        Hooks.message = Hooks.message + "Claim ID: [" + ClaimNumber + "]\n";
        if (ClaimNumber == null || ClaimNumber.trim().equalsIgnoreCase("")) {
            sc.write("Claim ID: " + ClaimNumber + "  not found in the file");
            throw new Exception("ClaimID not found in the file, Check Claim Data file");
        }
        base.Common.sleep(2000);
        waitForPageLoaded(driver, 30);// 30);
        driver.switchTo().parentFrame();
        cp.UserSelectSearchTypeRecord("claims");
        base.Common.sleep(2000);
        base.Common.highLighterMethod(driver, cp.SearchMainPage_txt);
        cp.getEnterAndSearchItem(ClaimNumber, "Claim ID");
        boolean columnExist = base.Common.checkColumnExistInDataSheet(dataMap, "ClaimReleationShip");
        if (columnExist) {
            System.out.println("Select Claim Releation");
            if (dataMap.get(rownumber).get("ClaimReleationShip").trim().equalsIgnoreCase("Yes")) {
                base.Common.waitHighlightAndClickNoscroll(driver, cp.ClaimantInsured_dropdown, sc, "ClaimantInsured_dropdown", 20, 2);
                base.Common.sleep(2000);
                base.Common.waitAndJsClick(driver, cp.Edit1_lnk, sc, "CoveragesShowActionsEdit_lnk", 20, 2);
                base.Common.sleep(2000);
                base.Common.waitHighlightAndClickNoscroll(driver, cp.ReleationShipType_drpdwn, sc, "ReleationShipType_drpdwn", 20, 2);
                String RT = dataMap.get(rownumber).get("ReleationType");
                String ReletionType = "//lightning-combobox/div[1]/lightning-base-combobox/div/div[2]/lightning-base-combobox-item/span/span[text()='" + RT + "']";
                WebElement RTOption = driver.findElement(By.xpath(ReletionType));
                base.Common.scrollonElement(driver, RTOption).click();
                base.Common.waitHighlightAndClick(driver, cp.AppliesTo_chkbx, sc, "AppliesTo_chkbx", 20, 2);
                base.Common.waitHighlightAndClick(driver, cs.Save_button, sc, "Save Button in Claim Relation Page", 20, 2);
            }
        }
    }

