    @Given("^Verify Claim Page (.*) Dropdown Values (\\d+)$")
    public void verifyTakeDPvalue(String dropType, int rownumber) throws Exception {
        System.out.println("\n[--- Start Step ---]");
        Hooks.iterationID = rownumber;
        System.out.println("[Step Iteration# " + rownumber + " ]");
        //------------------------------------
        tcid = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg")
                || FeatureDriver.testPlan.contains("BACKLOG") ? dataMap.get(rownumber).get("TCID") : "");
        tcname = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg")
                || FeatureDriver.testPlan.contains("BACKLOG") ? dataMap.get(rownumber).get("TCName") : "");
        if (tcid != null && !tcid.trim().equalsIgnoreCase(""))
            base.Common.writeconsule(sc, "TCID: " + tcid + " TC Name: " + tcname);
        //----------------------------------------------------
        if (dropType.equalsIgnoreCase("Task")) {
            List<String> searchInputs = Arrays.asList("Medical Review Walk-Up",
                    "75 days follow up", "105 days follow up");
            List<String> expectedResults = Arrays.asList(
                    "Medical Review Walk-Up (needed for LTD Migration Clinical Review)",
                    "75 days follow up (needed for Migration POL follow up process)",
                    "105 days follow up (needed for Migration POL follow up process)");
            for (int i = 0; i < searchInputs.size(); i++) {
                String input = searchInputs.get(i);
                String expected = expectedResults.get(i);
                WebElement searchBox = driver.findElement(By.xpath("//label[text()='Subject']/..//input"));
                searchBox.sendKeys(Keys.chord(Keys.CONTROL, "a", Keys.DELETE));
                searchBox.sendKeys(input);
                String actualTitle = base.Common.waitAndGetAttribute(driver, By.xpath("//label[text()='Subject']/..//lightning-base-combobox-formatted-text"),
                        "title", sc, "", false, true, 4, 2);
                base.Common.takeScreenshot(sc, driver, "actualTitleTask");
                Assert.assertTrue(actualTitle.equals(expected),
                        "Failed for input: " + input + ". Expected: " + expected + ", but got: " + actualTitle);
            }
        } else if (dropType.equalsIgnoreCase("Priority")) {
            System.out.println("ThisisPreiority");
            base.Common.Click(driver, By.xpath("//span//span[text()='Priority']/ancestor::div[1]//a"), sc,
                    "", true, false, true, false, 2, 1);
            Thread.sleep(500);
            List<WebElement> options = driver.findElements(By.xpath("(//div[@data-aura-class=\"uiPopupTarget uiMenuList uiMenuList--default uiMenuList--left uiMenuList--short\"])[2]//li/a"));
            List<String> actualValues = new ArrayList<>();
            for (WebElement option : options) {
                actualValues.add(option.getAttribute("title"));
                base.Common.highLighterMethod(driver, option);
                System.out.println("actualValues-->" + actualValues);
            }
            List<String> expectedValues = Arrays.asList("--None--", "PG", "High", "Normal", "BH", "PG BH");
            for (String expected : expectedValues) {
                Assert.assertTrue(actualValues.contains(expected), "Value not found: " + expected);
            }
        }
    }

