    @And("^Update (.*) field in PH (\\d+)$")
    public void UpdateMatrixClientCode(String fileTobeUpdate, int rownumber) throws Exception {
        if (fileTobeUpdate.equalsIgnoreCase("MatrixClientCode")) {
            base.Common.EnterData(driver, By.xpath("//input[@name='MatrixClientCode__c']"), "1234", sc, "MatrixClientCode ", true, true, true, true, false, 2, 1);
            base.Common.takeScreenshot(sc, driver, "MatrixClientCode");
        }
        if (fileTobeUpdate.equalsIgnoreCase("pacsID")) {
            base.Common.EnterData(driver, By.xpath("//input[@name='PacsId__c']"), dataMap.get(rownumber).get("PACScustomerID"), sc, "PacsID", true, true, true, true, false, 2, 1);
            base.Common.takeScreenshot(sc, driver, "PacsID");
        }
        if (fileTobeUpdate.equalsIgnoreCase("AddMatrixCode")) {
            boolean MatrixClientCodecolumnexist = base.Common.checkColumnExistInDataSheet(dataMap.get(rownumber), "MatrixClientCode");
            if (MatrixClientCodecolumnexist && !dataMap.get(rownumber).get("MatrixClientCode").equalsIgnoreCase("")) {
                base.Common.EnterData(driver, By.xpath("//input[@name='MatrixClientCode__c']"),
                        dataMap.get(rownumber).get("MatrixClientCode"), sc, "Q4", false, true, true, true, false, 2, 1);
            }
            base.Common.takeScreenshot(sc, driver, "MatrixClientCode");
        }
        if (fileTobeUpdate.equalsIgnoreCase("RemoveMatrixCode")) {
            boolean MatrixClientCodecolumnexist = base.Common.checkColumnExistInDataSheet(dataMap.get(rownumber), "MatrixClientCode");
            if (MatrixClientCodecolumnexist && !dataMap.get(rownumber).get("MatrixClientCode").equalsIgnoreCase("")) {
                WebElement elmt = driver.findElement(By.xpath("//input[@name='MatrixClientCode__c']"));
                base.Common.scrollandhighLighterMethod(driver, elmt);
                JavascriptExecutor js = (JavascriptExecutor) driver;
//                js.executeScript("arguments[0].value = '';", elmt);
                js.executeScript("arguments[0].value = ''; arguments[0].dispatchEvent(new Event('input'));", elmt);
//                base.Common.EnterData(driver, By.xpath("//input[@name='MatrixClientCode__c']"),
//                        dataMap.get(rownumber).get("MatrixClientCode"), sc, "", true, true, true, true, false, 2, 1);
            }
            base.Common.takeScreenshot(sc, driver, "MatrixClientCode");
        }
        base.Common.waitHighlightAndClickNoscroll(driver, pl.Save_btn, sc, "Save button", 20, 2);
    }

