    @Given("^Click on Product and Click On Benefit (\\d+)$")
    public void ClickonProdcutandClickonBenefit(int rownumber) throws Exception {
        stepPrerequisite(rownumber);
        System.out.println("\n[--- Start Step ---]");
        Hooks.iterationID = rownumber;
        System.out.println("[Step Iteration# " + rownumber + " ]");
        //------------------------------------
        tcid = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCID") : "");
        tcname = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCName") : "");
        if (tcid != null && !tcid.trim().equalsIgnoreCase(""))
            base.Common.writeconsule(sc, "[ TCID: " + tcid + " TCName: " + tcname + "]");
        //-----------------------------------
        String prodname = (dataMap.get(rownumber).get("ProdName").trim());
        System.out.println("Product Name--> " + prodname);
        String custFilename = Common.getProductdatafile(prodname);
        System.out.println("Property file path: " + custFilename);
        String EIS_PACSCustName = base.Common.readPropertFile(custFilename, Common.convertKeyWithPrefix("PACSCustName", tcid));
        System.out.println("PolicyCutName-->" + EIS_PACSCustName);
        String prodName = prodname;
        String EIS_PolicyID = "";
        if (prodName.trim().equalsIgnoreCase("HI")) {
            prodName = "VHI";
        } else if (prodName.trim().equalsIgnoreCase("CI")) {
            prodName = "VCI";
        } else if (prodName.trim().equalsIgnoreCase("AC")) {
            prodName = "VAI";
        } else if (prodName.trim().equalsIgnoreCase("STD")) {
            prodName = "STD";
        } else if (prodName.trim().equalsIgnoreCase("VPS")) {
            prodName = "VPS";
        } else if (prodName.trim().equalsIgnoreCase("TDI")) {
            prodName = "TDI";
        } else if (prodName.trim().equalsIgnoreCase("DBL")) {
            prodName = "DBL";
        } else if (prodName.trim().equalsIgnoreCase("BACKLOG")) {
            prodName = dataMap.get(rownumber).get("LineofBusinessAcronym");
            if (prodName.equalsIgnoreCase("STD")) {
                prodName = "STD";
            }
        }
        base.Common.Click(driver, By.xpath("//slot[contains(text(),'Policy Benefits')]/ancestor::a"), sc, "Policy Benefits", false, false, true, false, 5, 2);
        if (prodName.equalsIgnoreCase("STD") || prodName.equalsIgnoreCase("VPS") || prodName.equalsIgnoreCase("TDI") || prodName.equalsIgnoreCase("DBL") || prodName.equalsIgnoreCase("MAL") || prodName.equalsIgnoreCase("CTL") || prodName.equalsIgnoreCase("TDB")) {
            String BenefitName = "";
            if (prodName.equalsIgnoreCase("STD")) {
                BenefitName = "STDMaster-STD Plan 1-Core";
            } else if (prodName.equalsIgnoreCase("VPS")) {
                BenefitName = "STDMaster-VPS Plan 1-Core";
            } else if (prodName.equalsIgnoreCase("TDI")) {
                BenefitName = "SMPMaster-Statutory-TDI";
            } else if (prodName.equalsIgnoreCase("DBL")) {
                BenefitName = "SMPMaster-Statutory-DBL";
            } else if (prodName.equalsIgnoreCase("TDB")) {
                BenefitName = "SMPMaster-Statutory-TDB";
            } else if (prodName.equalsIgnoreCase("MAL")) {
                BenefitName = "SMPMaster-Statutory-MAL";
            } else if (prodName.equalsIgnoreCase("CTL")) {
                BenefitName = "SMPMaster-Statutory-CTL";
            }
            Thread.sleep(1000);
            base.Common.Click(driver, By.xpath("(//span[text()='" + BenefitName + "'])[1]"), sc, "Policy Core Benefit", false, false, true, false, 5, 2);
        }
    }

    @Given("^Click on Coverage and Verify EIS Benefits In CV Details Screen (\\d+)$")
    public void ClickonCoverageandVerifyEISBenefitsInCVDetailsScreen1(int rownumber) throws Exception {
        System.out.println("\n[--- Start Step ---]");
        Hooks.iterationID = rownumber;
        System.out.println("[Step Iteration# " + rownumber + " ]");
        //rownumber = rownumber - 1;
        //------------------------------------
        tcid = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCID") : "");
        tcname = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCName") : "");
        if (tcid != null && !tcid.trim().equalsIgnoreCase(""))
            base.Common.writeconsule(sc, "[ TCID: " + tcid + " TCName: " + tcname + "]");
        //------------------------------------
        waitForPageLoaded(driver, 30);// 30);
        driver.switchTo().parentFrame();
        String prodname = (dataMap.get(rownumber).get("ProdName").trim());
        String custFilename = Common.getProductdatafile(prodname);
        String EIS_HI_EmployerFacilityBenefit = base.Common.readPropertFile(custFilename, Common.convertKeyWithPrefix("Coverage2_EFB", tcid).trim());
        base.Common.writeconsule(sc, "Employer Facility Benefit-->" + EIS_HI_EmployerFacilityBenefit);
        String EIS_HI_HospitalConfinement = base.Common.readPropertFile(custFilename, Common.convertKeyWithPrefix("Coverage1_HC", tcid).trim());
        base.Common.writeconsule(sc, "HospitalConfinement-->" + EIS_HI_HospitalConfinement);
        base.Common.pageRefresh(driver);
        Thread.sleep(4000);
        base.Common.waitAndClick(driver, cp.BenefitsName_lnk, sc, "Benefits link", true, false, true, 30, 2);
        base.Common.sleep(2000);
        base.Common.waitHighlightAndClickNoscroll(driver, ab.Benefits_lnk, sc, "Benefit Name link", 20, 2);
        base.Common.sleep(2000);
        clickOnReleatedButton();
        base.Common.sleep(2000);
        //        base.Common.waitHighlightAndClickNoscroll(driver, cp.Coverages_lnk, sc, "Coverage link", 20, 2);
        if (prodname.equalsIgnoreCase("HI")) {
            String acctCVCoverageEC;
            String acctCVCoverage_EFB;
            if (base.Common.isElementDisply(cp.HospitalConfinement_lbl, sc, "Coverage1- Hospital Confinement", 4)) {
                acctCVCoverageEC = cp.HospitalConfinement_lbl.getText().trim();
                System.out.println("acctCVCoverageEC-->" + acctCVCoverageEC);
            } else {
                throw new Exception("VHI Benefit 1 - Hospital Confinement record NOT found under Coverage page");
            }
            if (base.Common.isElementDisply(cp.EmployerFacilityBenefit_lbl, sc, "Coverage2- Employer Facility Benefit", 4)) {
                acctCVCoverage_EFB = cp.EmployerFacilityBenefit_lbl.getText().trim();
                System.out.println("acctCVCoverage_EFB-->" + acctCVCoverage_EFB);
            } else {
                throw new Exception("VHI Benefit 2 - Employer Facility Benefit record NOT found under Coverage page ");
            }
            String errormsg = "";
            if (EIS_HI_HospitalConfinement.equals(acctCVCoverageEC)) {
                Hooks.message = Hooks.message + "EIS HospitalConfinement Data Verified --> " + "[" + acctCVCoverageEC + "] " + "\n";
            } else {
                errormsg = errormsg + "EIS HospitalConfinement  Data Verified [FAIL] " + "Expected: [" + EIS_HI_HospitalConfinement + "]  Actual: [" + acctCVCoverageEC + "]\n";
            }
            if (EIS_HI_EmployerFacilityBenefit.equalsIgnoreCase(acctCVCoverage_EFB)) {
                Hooks.message = Hooks.message + "EIS EmployerFacilityBenefit Data Verified --> " + "[" + EIS_HI_EmployerFacilityBenefit + "] " + "\n";
            } else {
                errormsg = errormsg + " EIS EmployerFacilityBenefit Verified [FAIL] " + "Expected : [" + EIS_HI_EmployerFacilityBenefit + "] Actual: [" + acctCVCoverage_EFB + "]\n";
            }
            if (!errormsg.trim().equalsIgnoreCase("")) {
                System.out.println("ErrorMessage-->" + errormsg);
                sc.write(errormsg);
                throw new Exception(errormsg);
            }
            base.Common.takeScreenshot(sc, driver, "EIS Data in CV Coverage Screen");
            base.Common.writeconsule(sc, "EIS Data validation in CV --> Benefit1: [" + EIS_HI_HospitalConfinement + "] " + "Benefit2: [" + EIS_HI_EmployerFacilityBenefit + "]");
            Hooks.message = Hooks.message + "EIS Policy Details In CV Policy Details Screen --> Benefit1: [" + EIS_HI_HospitalConfinement + "] " + "\n" + "Benefit2: [" + EIS_HI_EmployerFacilityBenefit + "] " + "\n";
        } else if (prodname.equalsIgnoreCase("AC")) {
        } else if (prodname.equalsIgnoreCase("CI")) {
        }
    }

