    @Given("^Verify Payment Track History (.*) (\\d+)$")
    public void verifyPaymentTrackHistory(String paymentSubmitType, int rownumber) throws Exception {
        stepPrerequisite(rownumber);
        String PaymentStatus = "";
        String OriginalValue = "";
        if (paymentSubmitType.equalsIgnoreCase("Approve")) {
            PaymentStatus = base.Common.waitAndGetText(driver, cp.PaymentHistoryNewValue, sc, "NewValue", 2, 2);
            OriginalValue = base.Common.waitAndGetText(driver, cp.OriginalValue, sc, "OriginalValue", 2, 2);
            Assert.assertEquals(PaymentStatus, "Submitted for Approval");
            Assert.assertEquals(OriginalValue, "Pending");
        } else if (paymentSubmitType.equalsIgnoreCase("Void")) {
            PaymentStatus = base.Common.waitAndGetText(driver, cp.PaymentHistoryNewValue, sc, "NewValue", 2, 2);
            OriginalValue = base.Common.waitAndGetText(driver, cp.OriginalValue, sc, "OriginalValue", 2, 2);
            Assert.assertEquals(PaymentStatus, "Submitted for Approval");
            Assert.assertEquals(OriginalValue, "Pending");
        }
    }

