    public void clickDrpDwnValue(By locator, String value) throws InterruptedException {
        if (!value.equalsIgnoreCase("")) {
            WebElement wbElement = driver.findElement(locator);
            wbElement.click();
            WebElement option = driver.findElement(By.xpath("//ul[@aria-label='Suggested For You']//span[text()='" + value + "']"));
            base.Common.scrollonElement(driver, option);
            option.click();
            Thread.sleep(1000);
        }
    }

