            System.out.println("PaymentListTable-->" + PaymentListTable.get(j));
            String statusText = PaymentListTable.get(j).getText();
            System.out.println("StatusText[" + j + "] --> " + statusText);
            WebElement PaymentListTableStatus = PaymentListTable.get(j).findElement(By.xpath(".//lightning-primitive-cell-factory[@data-label='Status']/span//lightning-base-formatted-text"));
            StatusValue = base.Common.waitAndGetText(driver, PaymentListTableStatus, sc, "", false, true, 5, 2);
