    public boolean isCheckboxSelectedByPseudo(WebDriver driver, By locator) {
        WebElement element = driver.findElement(locator);
        JavascriptExecutor js = (JavascriptExecutor) driver;
        String afterContent = (String) js.executeScript(
                "return window.getComputedStyle(arguments[0], '::after').getPropertyValue('content');",
                element);
        return afterContent != null && !afterContent.equals("none") && !afterContent.equals("\"\"");
    }

