    @And("^Update DOL With (.*) Date (\\d+)$")
    public void updateDOLwithpastdate(String FutureAndPastDays, int rownumber) throws Exception {
        System.out.println("\n[--- Start Step ---]");
        Hooks.iterationID = rownumber;
        System.out.println("[Step Iteration# " + rownumber + " ]");
        //rownumber = rownumber - 1;
        //------------------------------------
        tcid = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCID") : "");
        tcname = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCName") : "");
        if (tcid != null && !tcid.trim().equalsIgnoreCase(""))
            base.Common.writeconsule(sc, "[ TCID: " + tcid + " TCName: " + tcname + "]");
        //--------------------------------------------------
        LocalDate todayDate = LocalDate.now();
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("MM/dd/yyyy");
        Thread.sleep(2000);
        String PastDate = todayDate.plusDays(-10).format(formatter);
        String FutureDate = todayDate.plusDays(10).format(formatter);
        Thread.sleep(2000);
        System.out.println("PastDate-->" + PastDate);
        System.out.println("FutureDate-->" + FutureDate);
        if (FutureAndPastDays.equalsIgnoreCase("PAST")) {
            base.Common.EnterData(driver, cp.DOLDate, PastDate, sc, "DOLDate", false, true, true, true, false, 4, 1);
        } else if (FutureAndPastDays.equalsIgnoreCase("FUTURE")) {
            base.Common.EnterData(driver, cp.DOLDate, FutureDate, sc, "DOLDate", false, true, true, true, false, 4, 1);
        }
        base.Common.Click(driver, cp.DOLDateUpdate, sc, "DOLDateUpdate", false, false, true, false, 4, 2);
    }

