    public void verifyClaimNumberFormat(String a, int rownumber) throws IOException {
        System.out.println(" STart Add Agnecy and Agent Management details");
        Hooks.iterationID = rownumber;
        System.out.println("[RUNNING ITERATIOIN]  #" + rownumber);
        //rownumber = rownumber - 1;
        //------------------------------------
        tcid = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCID") : "");
        tcname = (FeatureDriver.testPlan.contains("e2e") || FeatureDriver.testPlan.contains("R2STDReg") ? dataMap.get(rownumber).get("TCName") : "");
        if (tcid != null && !tcid.trim().equalsIgnoreCase(""))
            base.Common.writeconsule(sc, "[ TCID: " + tcid + " TCName: " + tcname + "]");
        //--------------------------------------------------------------------------------------------------
        base.Common.highLighterMethod(driver, cp.ClaimNumber_lbl);
        String ActualLOB = cp.ClaimNumber_lbl.getText().trim();
        base.Common.writeconsule(sc, "RSLIClaimNumber-->" + ActualLOB);
        Hooks.message = Hooks.message + "Actual RSL Claim Number: [" + ActualLOB + "]\n";
            /*int lenght = ActualLOB.length();
            String AfterSpiltAgentIDsecoundhalf = ActualLOB.substring(ActualLOB.length() - 4);*/
        String[] arrOfStr = ActualLOB.split("-");
        String AfterSpiltLOB = arrOfStr[0];
        String AfterSpiltYear = arrOfStr[1];
        String AfterSpiltMonth = arrOfStr[2];
        String AfterSpiltDate = arrOfStr[3];
        String AfterSpiltSlNo = arrOfStr[4];
        System.out.println("AfterSpiltLOB--> " + AfterSpiltLOB);
        System.out.println("AfterSpiltYear--> " + AfterSpiltYear);
        System.out.println("AfterSpiltMonth--> " + AfterSpiltMonth);
        System.out.println("AfterSpiltDate--> " + AfterSpiltDate);
        System.out.println("AfterSpiltSlNo--> " + AfterSpiltSlNo);
        SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy/MM/dd");
        Calendar c = Calendar.getInstance();
        String yeasrdatamonth = (String) (dateFormat.format(c.getTime()));
        sc.write("SystemCurrentYearmonthdate --> " + yeasrdatamonth);
        String[] spiltDateFormat = yeasrdatamonth.split("/");
        String Cyear = spiltDateFormat[0];
        String Cmonth = spiltDateFormat[1];
        String Cdate = spiltDateFormat[2];
        System.out.println("AfterSpiltCyear--> " + Cyear);
        System.out.println("AfterSpiltCmonth--> " + Cmonth);
        System.out.println("AfterSpiltCdate--> " + Cdate);
        String ExpDataLOB = dataMap.get(rownumber).get("LineofBusinessAcronym");
        Assert.assertEquals(AfterSpiltLOB, ExpDataLOB, "LOB Data Not Matched");
        Assert.assertEquals(Cyear, AfterSpiltYear, "Year Not Matched");
        Assert.assertEquals(Cmonth, AfterSpiltMonth, "Month Not Matched");
        //		Assert.assertEquals(Cdate,AfterSpiltDate,"Date Not Matched");
        base.Common.sleep(2000);
        Hooks.message = Hooks.message + "LOB: [" + ExpDataLOB + "]\n" + "Year: [" + AfterSpiltYear + "]\n" + "Month: [" + AfterSpiltMonth + "]\n";
        base.Common.takeScreenshot(sc, driver, "RSLI Claim Number");

            /*System.out.println("Agent ID Secound --> " + AfterSpiltAgentIDsecoundhalf);
            String ExpAgentLastFourDigits = dataMap.get(rownumber).get("AgentLastFourDigits");
            Assert.assertEquals(AfterSpiltAgentIDsecoundhalf,ExpAgentLastFourDigits,"For Indiviadula Agent Showing as -->"+AfterSpiltAgentIDsecoundhalf);
            base.Common.takeScreenshot(sc, driver, "Agent and Agency");*/
    }

