    @Given("Verify (.*) Delivery Method Dropdown values (\\d+)$")
    public void verifyDeliverymethodDropdownValues(String typeofletter, int rownumber) throws Exception {
        stepPrerequisite(rownumber);
        base.Common.Click(driver, cnd.DeliveryMethod_dropdwn, sc, "DeliveryMethod_dropdwn",
                false, false, true, false, 5, 2);
        List<WebElement> dropdownItems =
                driver.findElements(By.xpath("//div[@aria-label='Delivery Method']/lightning-base-combobox-item/span/span"));
        List<String> actualValues = dropdownItems.stream()
                .map(WebElement::getText)
                .map(String::trim)
                .collect(Collectors.toList());
        if (dataMap.get(rownumber).get("TCID").equalsIgnoreCase("304413") ||
                dataMap.get(rownumber).get("TCID").equalsIgnoreCase("304402")) {
            List<String> expectedValues = Arrays.asList("None");
            System.out.println("ActualDropdownValues:");
            for (String val : actualValues) {
                System.out.println(" - " + val);
            }
            for (String expected : expectedValues) {
                System.out.println("DropdownExpValue: " + expected);
                System.out.println("DropdownAccValues: " + actualValues);
                Assert.assertFalse(actualValues.contains(expected), "DeliveryMethodShowing : " + expected);
            }
            System.out.println("Expected Values: " + expectedValues);
            System.out.println("Actual Values: " + actualValues);
        } else {
            List<String> expectedValues = Arrays.asList("Email", "Fax", "Print");
            System.out.println("ActualDropdownValues:");
            for (String val : actualValues) {
                System.out.println(" - " + val);
            }
            for (String expected : expectedValues) {
                System.out.println("DropdownExpValue: " + expected);
                System.out.println("DropdownAccValues: " + actualValues);
                Assert.assertTrue(actualValues.contains(expected), "Missing value: " + expected);
            }
            System.out.println("Expected Values: " + expectedValues);
            System.out.println("Actual Values: " + actualValues);
        }
    }

